const expectedNumbers = [
    "000000000500511057",
    "000000000500512254",
    "000000000500567038",
    "000000000500562173"
];

const responseData = pm.response.json();

pm.test("Response is an array of 4 items", function () {
    pm.expect(responseData).to.be.an('array');
    pm.expect(responseData).to.have.lengthOf(expectedNumbers.length);
});

pm.test("Response contains all expected numbers", function () {
    const actualNumbers = responseData.map(entry => entry.Number);

    expectedNumbers.forEach(num => {
        pm.expect(actualNumbers).to.include(num);
    });
});
